import { uuidv4 } from '../../../core/utils/uuidv4.js';
import { TimeseriesAnnotationsTrackConfig } from '../../timeseries/types/timeseries-config.js';

export const identifyMarkers = (tracks: TimeseriesAnnotationsTrackConfig[]) => {
  const identifiedTracks: TimeseriesAnnotationsTrackConfig[] = [];
  tracks.forEach((track) => {
    const currentTrack = {
      ...track,
      markers: track.markers.map((marker) => ({ ...marker, id: uuidv4() })),
    };
    identifiedTracks.push(currentTrack);
  });

  return identifiedTracks;
};
